contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test: take a deposit amount, deposit it, then attempt withdrawAll.
    // If withdrawAll succeeds, then afterwards an observable check (deposit 0 then withdrawAll) must see caller credit zero
    // and C's balance must not have increased as a result of the successful withdraw.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (0)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // record balances before any interaction
        uint beforeC = address(c).balance;

        // make a deposit (may be zero)
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;

        // To observe the caller's stored credit after the withdraw (only observable via behavior),
        // we perform a deposit of 0 to avoid changing state, then call withdrawAll again and see if it succeeds.
        // If the recorded credit is zero, withdrawAll should succeed but transfer 0 (i.e., not revert because of callResult),
        // and C's balance should not increase compared to afterC. We capture whether this second withdraw reverted.
        bool secondReverted;
        // deposit 0 is allowed and changes credit by +0
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: either the first withdraw reverted, or (1) the second withdraw did not revert (meaning caller had no positive credit left)
        // and (2) the contract's balance did not increase as a result of the first withdraw (i.e., afterC <= beforeC).
        assert(reverted || (!secondReverted && afterC <= beforeC));
    }

    // accept Ether sent back from C
    receive() external payable {}
}

